package com.readwide.manager.archive;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import java.io.*;import java.nio.file.*;import java.util.*;
import static org.junit.Assert.*;
public class SevenZSwapRound4Test {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void scalarOracleMatchesRandomReadBoundaries()throws Exception{Random random=new Random(416);for(int trial=0;trial<600;trial++){int width=trial%2==0?2:4;byte[] input=Round4Fixtures.data(random.nextInt(170000)),expected=Round4Fixtures.swap(input,width);int chunk=1+random.nextInt(901);ByteArrayInputStream source=new ByteArrayInputStream(input){public synchronized int read(byte[]b,int o,int n){return super.read(b,o,Math.min(chunk,n));}};ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream stream=new SevenZSwapInputStream(source,width)){byte[] buffer=new byte[1+random.nextInt(1234)];int n;while((n=stream.read(buffer))!=-1)out.write(buffer,0,n);assertEquals(-1,stream.read());}assertArrayEquals("trial="+trial,expected,out.toByteArray());}}
 @Test public void allShortTailsArePreserved()throws Exception{for(int width:new int[]{2,4})for(int n=0;n<12;n++){byte[] raw=Round4Fixtures.data(n);try(InputStream stream=new SevenZSwapInputStream(new ByteArrayInputStream(raw),width)){assertArrayEquals(Round4Fixtures.swap(raw,width),stream.readAllBytes());}}}
 @Test public void singleByteReadsMatchOracle()throws Exception{byte[] raw=Round4Fixtures.data(501);try(InputStream in=new SevenZSwapInputStream(new ByteArrayInputStream(raw),4)){for(byte b:Round4Fixtures.swap(raw,4))assertEquals(b&255,in.read());assertEquals(-1,in.read());}}
 @Test public void skipDoesNotBypassTransform()throws Exception{byte[] raw=Round4Fixtures.data(100003);try(InputStream in=new SevenZSwapInputStream(new ByteArrayInputStream(raw),4)){assertEquals(3,in.skip(3));assertArrayEquals(Arrays.copyOfRange(Round4Fixtures.swap(raw,4),3,raw.length),in.readAllBytes());}}
 @Test public void zeroProgressFailureIsSticky()throws Exception{InputStream source=new InputStream(){public int read(){return 0;}public int read(byte[]b,int o,int n){return 0;}};try(InputStream in=new SevenZSwapInputStream(source,2)){IOException first=assertThrows(IOException.class,in::read);assertSame(first,assertThrows(IOException.class,in::read));}}
 @Test public void invalidCountsRejected()throws Exception{try(InputStream in=new SevenZSwapInputStream(new InputStream(){public int read(){return -1;}public int read(byte[]b,int o,int n){return n+1;}},4)){assertThrows(IOException.class,in::read);}}
 @Test public void cancellationPreservesFlagAndIsSticky()throws Exception{try(InputStream in=new SevenZSwapInputStream(new ByteArrayInputStream(new byte[9]),4)){Thread.currentThread().interrupt();IOException first=assertThrows(InterruptedIOException.class,in::read);assertTrue(Thread.interrupted());assertSame(first,assertThrows(IOException.class,in::read));}finally{Thread.interrupted();}}
 @Test public void closeOwnsSourceOnceAndRejectsReads()throws Exception{class Source extends ByteArrayInputStream{int closed;Source(){super(new byte[4]);}public void close(){closed++;}}Source s=new Source();InputStream in=new SevenZSwapInputStream(s,2);in.close();in.close();assertEquals(1,s.closed);assertThrows(IOException.class,in::read);}
 @Test public void invalidArgumentsAndZeroLength()throws Exception{assertThrows(IllegalArgumentException.class,()->new SevenZSwapInputStream(new ByteArrayInputStream(new byte[0]),3));try(InputStream in=new SevenZSwapInputStream(new ByteArrayInputStream(new byte[0]),2)){assertEquals(0,in.read(new byte[0]));assertThrows(IndexOutOfBoundsException.class,()->in.read(new byte[3],2,2));}}
 private void archive(int width,boolean aes,boolean header,int size)throws Exception{byte[] raw=Round4Fixtures.data(size);File file=Round4Fixtures.sevenZ(temp.newFolder(),raw,width,aes,header,false,false),out=temp.newFile();assertTrue(SevenZBcj2ArchiveReader.archiveUsesSpecialCoder(file,aes?Round4Fixtures.PASSWORD:null));assertTrue(SevenZBcj2ArchiveReader.extractSingleEntry(file,"data.bin",out,aes?Round4Fixtures.PASSWORD:null));assertArrayEquals(raw,Files.readAllBytes(out.toPath()));}
 @Test public void swap2ContainerExtracts()throws Exception{archive(2,false,false,200003);}
 @Test public void swap4ContainerExtracts()throws Exception{archive(4,false,false,200003);}
 @Test public void swap2AesContainerExtracts()throws Exception{archive(2,true,false,19999);}
 @Test public void swap4AesContainerExtracts()throws Exception{archive(4,true,false,19999);}
 @Test public void swap2EncodedHeaderExtracts()throws Exception{archive(2,false,true,301);}
 @Test public void swap4AesEncodedHeaderExtracts()throws Exception{archive(4,true,true,309);}
 @Test public void zeroSizeSwapFolderExtracts()throws Exception{archive(4,false,false,0);}
 @Test public void wrongAesPasswordPreservesOutput()throws Exception{File file=Round4Fixtures.sevenZ(temp.newFolder(),Round4Fixtures.data(40),4,true,false,false,false),out=temp.newFile();Files.write(out.toPath(),new byte[]{6});assertThrows(IOException.class,()->SevenZBcj2ArchiveReader.extractSingleEntry(file,"data.bin",out,"wrong".toCharArray()));assertArrayEquals(new byte[]{6},Files.readAllBytes(out.toPath()));}
 @Test public void badFolderCrcPreservesOutput()throws Exception{File file=Round4Fixtures.sevenZ(temp.newFolder(),Round4Fixtures.data(40),4,false,false,true,false),out=temp.newFile();Files.write(out.toPath(),new byte[]{6});assertThrows(IOException.class,()->SevenZBcj2ArchiveReader.extractSingleEntry(file,"data.bin",out,null));assertArrayEquals(new byte[]{6},Files.readAllBytes(out.toPath()));}
 private void forward(ArchiveSupport.ForwardArchiveReader reader,byte[] raw)throws Exception{assertNotNull(reader);try(ArchiveSupport.ForwardArchiveReader in=reader){for(int i=0;i<2;i++){assertEquals((i+1)+".bin",in.nextEntry().path);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[37];int n;while((n=in.read(b))!=-1)out.write(b,0,n);int mid=raw.length/2;assertArrayEquals(i==0?Arrays.copyOfRange(raw,0,mid):Arrays.copyOfRange(raw,mid,raw.length),out.toByteArray());}assertNull(in.nextEntry());}}
 @Test public void solidTwoFileForwardReaderCrossesWordBoundary()throws Exception{byte[] raw=Round4Fixtures.data(20006);File file=Round4Fixtures.sevenZ(temp.newFolder(),raw,4,false,false,false,true);forward(SevenZBcj2ArchiveReader.openSpecialForwardReader(file,null,temp.newFolder()),raw);}
 @Test public void splitAesEncodedHeaderForwardReader()throws Exception{byte[] raw=Round4Fixtures.data(20006);File dir=temp.newFolder(),file=Round4Fixtures.sevenZ(dir,raw,4,true,true,false,true);byte[] all=Files.readAllBytes(file.toPath());Files.delete(file.toPath());int[] cuts={0,3,31,117,all.length};File last=null;for(int i=0;i+1<cuts.length;i++)last=Round4Fixtures.write(dir,String.format(Locale.ROOT,"book.7z.%03d",i+1),Arrays.copyOfRange(all,cuts[i],cuts[i+1]));File spool=temp.newFolder();forward(SevenZBcj2ArchiveReader.openSpecialForwardReader(last,Round4Fixtures.PASSWORD,spool),raw);assertEquals(0,Objects.requireNonNull(spool.list()).length);}
 @Test public void allEntryExtractionUsesSwapFilter()throws Exception{byte[] raw=Round4Fixtures.data(50);File file=Round4Fixtures.sevenZ(temp.newFolder(),raw,2,false,false,false,true),out=temp.newFolder();assertTrue(SevenZBcj2ArchiveReader.extractArchiveIntoDirectory(file,out,null,null,null));assertArrayEquals(Arrays.copyOfRange(raw,0,25),Files.readAllBytes(new File(out,"1.bin").toPath()));assertArrayEquals(Arrays.copyOfRange(raw,25,50),Files.readAllBytes(new File(out,"2.bin").toPath()));}

 @Test public void registryDeclaresBothSwapFiltersAndRejectsProperties()throws Exception{assertEquals(20,SevenZCoderRegistry.entries().size());for(int width:new int[]{2,4}){byte[] id={2,3,(byte)width};assertTrue(SevenZCoderRegistry.requiresSupplemental(id));assertThrows(IOException.class,()->SevenZCoderRegistry.find(id).prepare(new byte[]{1},10));}assertNull(SevenZCoderRegistry.find(new byte[]{2,3,3}));}
 private static InputStream innerStream(String name,Class<?>[] args,Object... values)throws Exception{Class<?> c=Class.forName("com.readwide.manager.archive.SevenZBcj2ArchiveReader$"+name);java.lang.reflect.Constructor<?> constructor=c.getDeclaredConstructor(args);constructor.setAccessible(true);return (InputStream)constructor.newInstance(values);}
 private static InputStream noProgress(){return new InputStream(){public int read(){return 0;}public int read(byte[]b,int o,int n){return 0;}};}
 @Test public void exactStreamRejectsNonProgressingCodec()throws Exception{try(InputStream in=innerStream("ExactStream",new Class<?>[]{InputStream.class,long.class},noProgress(),1L)){assertThrows(IOException.class,()->in.read(new byte[1]));}}
 @Test public void integrityStreamRejectsNonProgressingCodec()throws Exception{try(InputStream in=innerStream("IntegrityStream",new Class<?>[]{InputStream.class,long.class,long.class,long[].class,long[].class},noProgress(),1L,-1L,new long[]{1},new long[]{-1})){assertThrows(IOException.class,()->in.read(new byte[1]));}}
 @Test public void swapOnlyInEncryptedHeaderStillRoutesAndExtracts()throws Exception{byte[] raw=Round4Fixtures.data(129);File file=Round4Fixtures.sevenZ(temp.newFolder(),raw,4,true,true,false,false,true),out=temp.newFile();assertTrue(SevenZBcj2ArchiveReader.archiveUsesSpecialCoder(file,Round4Fixtures.PASSWORD));assertTrue(SevenZBcj2ArchiveReader.extractSingleEntry(file,"data.bin",out,Round4Fixtures.PASSWORD));assertArrayEquals(raw,Files.readAllBytes(out.toPath()));}
}
